package com.medicore.prescription.controller; import com.medicore.prescription.dto.*; import com.medicore.prescription.service.PrescriptionService; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/prescriptions") public class PrescriptionController {private final PrescriptionService service; public PrescriptionController(PrescriptionService service){this.service=service;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public PrescriptionResponse create(@Valid @RequestBody PrescriptionRequest r){return service.create(r);} @GetMapping("/{id}") public PrescriptionResponse find(@PathVariable Long id){return service.find(id);} @PatchMapping("/{id}/status") public PrescriptionResponse status(@PathVariable Long id,@RequestParam String value){return service.status(id,value);}}
